int main() {
    std::thread t([] {
        std::cout << "worker done\n";
    });
    std::this_thread::sleep_for(
        std::chrono::milliseconds(100));
    t.join();
    std::cout << "main done\n";
}

void foo() {
    int value = 42;
    std::thread t([&] { std::cout << value; });
    t.detach();
}

int main() {
    int value = 42;

    std::thread t([](int& x) {
        x++;
        std::cout << x << '\n';
    }, value);

    t.join();
    std::cout << value << '\n';
}

