int* ptr = nullptr;
void worker() {
  int value = 42;
  ptr = &value;
}
int main() {
  std::thread t(worker);
  t.join();
  std::cout << *ptr << '\n';
}

int main() {
    int result = 0;             // owned by main
    std::thread t([&result] {
        result = 42;
    });
    t.join();     // write is visible after join
    std::cout << result << '\n';
}
